import org.springframework.web.bind.annotation.ControllerAdvice;
import org.springframework.web.servlet.mvc.method.annotation.ResponseBodyAdvice;

/**
 * Enqueues a welcome notification for a newly created owner. When the create endpoint
 * ({@code addOwner}) returns its {@link OwnerDto}, a single line carrying the owner id
 * and memberId is emitted on the dedicated {@code NOTIFY} logger. Purely a side-effect,
 * so it leaves the response body untouched.
 */
@ControllerAdvice
public class OwnerWelcomeNotificationAdvice implements ResponseBodyAdvice<Object> {

    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");

    @Override
    public boolean supports(MethodParameter returnType,
                            Class<? extends HttpMessageConverter<?>> converterType) {
        Method method = returnType.getMethod();
        return method != null && "addOwner".equals(method.getName());
    }

    @Override
    public Object beforeBodyWrite(Object body, MethodParameter returnType, MediaType selectedContentType,
                                  Class<? extends HttpMessageConverter<?>> selectedConverterType,
                                  ServerHttpRequest request, ServerHttpResponse response) {
        if (body instanceof OwnerDto owner) {
            NOTIFY.info("welcome owner id={} memberId={}", owner.getId(), owner.getMemberId());
        }
        return body;
    }
}

